/* eslint-disable no-restricted-globals */
import React, { useState, useRef, useEffect } from "react";
import "../RedactionPrototype.css";
import { apiService, UploadResponse, FileInfo } from "../../services/api";
import { useAuth } from "../../contexts/AuthContext";

interface Detection {
  type: string;
  bbox: [number, number, number, number];
}

interface FileData {
  id: string;
  name: string;
  url: string;
  detections: Detection[];
  redactions: any[];
}

export default function RedactionPrototype() {
  const [files, setFiles] = useState<FileData[]>([]);
  const [selected, setSelected] = useState<FileData | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [userFiles, setUserFiles] = useState<FileInfo[]>([]);
  const [minioStatus, setMinioStatus] = useState<'healthy' | 'unhealthy' | 'unknown'>('unknown');
  
  const { user } = useAuth();
  const fileInput = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (user) {
      loadUserFiles();
      checkMinioHealth();
    }
  }, [user]);

  const loadUserFiles = async () => {
    try {
      const files = await apiService.getUserFiles();
      setUserFiles(files);
    } catch (error) {
      console.error('Error loading user files:', error);
      setUserFiles([]);
    }
  };

  const checkMinioHealth = async () => {
    try {
      const isHealthy = await apiService.minioHealthCheck();
      setMinioStatus(isHealthy ? 'healthy' : 'unhealthy');
    } catch (error) {
      console.error('Error checking MinIO health:', error);
      setMinioStatus('unhealthy');
    }
  };

  async function handleFiles(rawFiles: FileList | null) {
    if (!rawFiles) return;

    setLoading(true);
    setError(null);

    try {
      console.log(`🔄 Uploading ${rawFiles.length} file(s)...`);
      
      const uploadResponses: UploadResponse[] = await apiService.uploadFiles(rawFiles);
      
      const newFiles: FileData[] = uploadResponses.map(response => ({
        id: response.id,
        name: response.name,
        url: response.url.startsWith('http') ? response.url : `http://localhost:8001${response.url}`,
        detections: response.detections,
        redactions: response.redactions
      }));

      setFiles(prev => [...newFiles, ...prev]);
      if (!selected) setSelected(newFiles[0]);
      
      await loadUserFiles();
      
      console.log(`✅ Upload successful: ${newFiles.length} file(s) uploaded`);
    } catch (error) {
      console.error('❌ Error uploading files:', error);
      setError(error instanceof Error ? error.message : 'Ошибка при загрузке файлов');
    } finally {
      setLoading(false);
    }
  }

  const handleFileDelete = async (fileId: string, objectName?: string) => {
    if (!confirm('Вы уверены, что хотите удалить этот файл?')) return;

    try {
      if (objectName) {
        await apiService.deleteFile(objectName);
      }
      
      setFiles(prev => prev.filter(f => f.id !== fileId));
      if (selected?.id === fileId) {
        setSelected(files.length > 1 ? files[1] : null);
      }
      
      await loadUserFiles();
      
      console.log('✅ File deleted');
    } catch (error) {
      console.error('❌ Error deleting file:', error);
      setError('Ошибка при удалении файла');
    }
  };

  return (
    <div className="redaction-container">
      <div className="redaction-header">
        <h1 className="redaction-title">Цензура персональных данных</h1>
        <div className="user-info-badge">
          {user && (
            <>
              <span className="user-icon">{user.is_admin ? '👑' : '👤'}</span>
              <span className="username">{user.username}</span>
              <span className={`storage-badge ${minioStatus}`}>
                {minioStatus === 'healthy' ? 'MinIO' : 'Local'}
              </span>
            </>
          )}
        </div>
      </div>

      <div className="system-info-card">
        <div className="info-item">
          <strong>Аутентификация:</strong> PostgreSQL
        </div>
        <div className="info-item">
          <strong>Хранилище:</strong> {minioStatus === 'healthy' ? 'MinIO' : 'Локальное'}
        </div>
        <div className="info-item">
          <strong>Пользователь:</strong> {user?.username || 'Не авторизован'}
        </div>
        <div className="info-item">
          <strong>Файлов:</strong> {userFiles.length}
        </div>
      </div>

      <div className="upload-section">
        <div className="upload-controls">
          <button
            onClick={() => fileInput.current?.click()}
            className="upload-button"
            disabled={loading || !user}
          >
            {loading ? 'Загрузка...' : '📁 Загрузить файлы'}
          </button>
        </div>
        
        <input
          type="file"
          ref={fileInput}
          multiple
          className="file-input"
          onChange={e => handleFiles(e.target.files)}
          accept="image/*"
          disabled={!user}
        />
        
        {!user && (
          <div className="auth-warning">
            ⚠️ Для загрузки файлов необходимо <a href="/login">войти в систему</a>
          </div>
        )}
        
        {error && (
          <div className="error-message">
            ❌ {error}
          </div>
        )}
      </div>

      {userFiles.length > 0 && (
        <div className="user-files-section">
          <h3>📁 Ваши файлы ({userFiles.length})</h3>
          <div className="files-grid">
            {userFiles.map((file, index) => (
              <div key={index} className="file-card">
                <div className="file-preview">
                  {file.name?.match(/\.(jpg|jpeg|png|gif)$/i) ? (
                    <img 
                      src={file.url} 
                      alt={file.name} 
                      className="file-thumbnail"
                      onError={(e) => {
                        (e.target as HTMLImageElement).src = '/placeholder-image.png';
                      }}
                    />
                  ) : (
                    <div className="file-icon">📄</div>
                  )}
                </div>
                <div className="file-info">
                  <div className="file-name">{file.name || file.object_name}</div>
                  <div className="file-size">
                    {file.size ? `${(file.size / 1024).toFixed(2)} KB` : 'Unknown size'}
                  </div>
                </div>
                <div className="file-actions">
                  {file.url && (
                    <a 
                      href={file.url} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="action-button view"
                      title="Просмотреть"
                    >
                      👁️
                    </a>
                  )}
                  <button 
                    onClick={() => handleFileDelete(index.toString(), file.object_name)}
                    className="action-button delete"
                    title="Удалить"
                  >
                    🗑️
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {files.length > 0 && (
        <div className="gallery-section">
          <h3>Обработанные изображения ({files.length})</h3>
          <div className="gallery">
            {files.map(f => (
              <div 
                key={f.id} 
                className={`gallery-item ${selected?.id === f.id ? "selected" : ""}`}
                onClick={() => setSelected(f)}
              >
                <img
                  src={f.url}
                  alt={f.name}
                  className="gallery-img"
                />
                <div className="image-info">
                  <span>{f.name}</span>
                  <span>{f.detections.length} лиц(о)</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {selected && (
        <div className="viewer-section">
          <h3>Просмотр и цензура: {selected.name}</h3>
          <div className="viewer-container">
            <img
              src={selected.url}
              alt={selected.name}
              className="viewer-img"
            />
            {selected.detections.map((d, i) => {
              const [x, y, w, h] = d.bbox;
              return (
                <div
                  key={i}
                  className="detection-box"
                  style={{
                    left: `${x * 100}%`,
                    top: `${y * 100}%`,
                    width: `${w * 100}%`,
                    height: `${h * 100}%`
                  }}
                >
                  <span className="detection-label">{d.type}</span>
                </div>
              );
            })}
          </div>
          <div className="detection-info">
            <h4>Обнаружено лиц: {selected.detections.length}</h4>
            <div className="detection-controls">
              <button className="control-button">
                🖌️ Применить цензуру
              </button>
              <a 
                href={selected.url} 
                download={selected.name}
                className="control-button"
              >
                ⬇️ Скачать
              </a>
            </div>
          </div>
        </div>
      )}

      <div className="system-status">
        <h3>Статус системы</h3>
        <div className="status-items">
          <div className={`status-item ${user ? 'success' : 'warning'}`}>
            <span className="status-icon">{user ? '✅' : '⚠️'}</span>
            Пользователь: {user ? 'Авторизован' : 'Не авторизован'}
          </div>
          <div className={`status-item ${minioStatus === 'healthy' ? 'success' : 'warning'}`}>
            <span className="status-icon">{minioStatus === 'healthy' ? '✅' : '⚠️'}</span>
            Хранилище: {minioStatus === 'healthy' ? 'MinIO работает' : 'Локальное'}
          </div>
          <div className="status-item success">
            <span className="status-icon">✅</span>
            API: Работает
          </div>
        </div>
      </div>
    </div>
  );
}
